package ar.demo.envios;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
class EsperaService {
    private final EnvioRepository repo;

    EsperaService(EnvioRepository repo) {
        this.repo = repo;
    }

    @Transactional
    long conConexion() throws InterruptedException {
        long n = repo.count();  // la transacción toma una conexión del pool
        Thread.sleep(500);      // y la retiene mientras dura el método
        return n;
    }
}

package ar.demo.envios;

import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
class EnvioService {
    private final EnvioRepository repo;

    EnvioService(EnvioRepository repo) {
        this.repo = repo;
    }

    @Transactional
    Envio crear(EnvioNuevo n) {
        return repo.save(new Envio(n.destino(), n.pesoKg(), n.prioridad()));
    }

    Envio buscar(Long id) {
        return repo.findById(id).orElseThrow(
                () -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No existe ese envío"));
    }

    List<Envio> listar(String estado) {
        return estado == null ? repo.findAll() : repo.findByEstado(estado);
    }
}

@RestController
@RequestMapping("/envios")
class EnvioController {
    private final EnvioService servicio;

    EnvioController(EnvioService servicio) {   // el contenedor pasa el bean acá
        this.servicio = servicio;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    Envio crear(@Valid @RequestBody EnvioNuevo nuevo) {
        return servicio.crear(nuevo);
    }
    // ... uno() y listar() siguen el mismo patrón
}

package ar.demo.envios;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;

@Entity
public class Envio {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String destino;
    private double pesoKg;
    private String prioridad;
    private String estado;

    protected Envio() {}  // JPA lo exige para poder armar objetos al leer filas

    public Envio(String destino, double pesoKg, String prioridad) {
        this.destino = destino;
        this.pesoKg = pesoKg;
        this.prioridad = prioridad == null ? "normal" : prioridad;
        this.estado = "pendiente";
    }

    public Long getId() { return id; }
    public String getDestino() { return destino; }
    public double getPesoKg() { return pesoKg; }
    public String getPrioridad() { return prioridad; }
    public String getEstado() { return estado; }
}

package ar.demo.envios;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

interface EnvioRepository extends JpaRepository<Envio, Long> {
    List<Envio> findByEstado(String estado);
}

package ar.demo.envios;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

public record EnvioNuevo(
        @NotBlank @Size(min = 3, max = 60) String destino,
        @DecimalMin(value = "0.0", inclusive = false) @DecimalMax("1000") double pesoKg,
        @Pattern(regexp = "normal|urgente") String prioridad) {}
